def render_toc_ul(toc: Iterable[Tuple[int, str, str]]) ->str:
    s = ''
    last_level = 0

    for level, heading_id, text in toc:
        if level > last_level:
            # Open new nested lists
            for _ in range(level - last_level):
                s += '<ul>\n'
        elif level < last_level:
            # Close nested lists
            for _ in range(last_level - level):
                s += '</ul>\n'

        s += '<li><a href="#' + heading_id + '">' + text + '</a></li>\n'
        last_level = level

    # Close remaining open lists
    for _ in range(last_level):
        s += '</ul>\n'

    return s
